using FlexExtractor;
using System.Windows.Forms;
static partial class Cases {
 public static void TestReviewRecentCopyFlowsFromWorkerToUi(){var c=Cfg(Fresh());c.SizeStableChecks=0;var source=Source(c);Sta(()=>{using var form=new FlexExtractor.UI.MainForm(c);var controls=AllControls(form).ToArray();foreach(var name in new[]{"RecentFile","RecentStation"})Program.Check(controls.Any(x=>x.Name==name),"missing recent status field "+name);var engine=new Engine(c);void PumpUntil(Func<bool> done){var clock=System.Diagnostics.Stopwatch.StartNew();while(!done()&&clock.Elapsed.TotalSeconds<9){Application.DoEvents();Thread.Sleep(10);}Program.Check(done(),"STA async operation exceeded9seconds");}try{engine.Start();PumpUntil(()=>engine.Snapshot.Copied>0);Program.Check(engine.Snapshot.Copied==1,"copy did not reach engine");typeof(FlexExtractor.UI.MainForm).GetField("engine",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.SetValue(form,engine);var refresh=typeof(FlexExtractor.UI.MainForm).GetMethod("RefreshView",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!;refresh.Invoke(form,null);Program.Check(controls.Single(x=>x.Name=="RecentFile").Text.Replace('/','\\').Contains(source.Replace('/','\\')),"recent copied file not propagated: expected="+source+" actual="+controls.Single(x=>x.Name=="RecentFile").Text+" snapshot="+engine.Snapshot.RecentFile);Program.Check(controls.Single(x=>x.Name=="RecentStation").Text.Contains(c.DispenseItems[0].StationName),"recent station not propagated");var idle=System.Diagnostics.Stopwatch.StartNew();PumpUntil(()=>idle.ElapsedMilliseconds>1600);refresh.Invoke(form,null);Program.Check(controls.Single(x=>x.Name=="RecentFile").Text.Replace('/','\\').Contains(source.Replace('/','\\')),"empty/idempotent pass erased recent file");}finally{var stop=engine.DisposeAsync().AsTask();PumpUntil(()=>stop.IsCompleted);stop.GetAwaiter().GetResult();}});}
}
